create type app_role as enum ('SUPER_ADMIN','ADMIN','FRIEND');
create type payment_status as enum ('PENDING','APPROVED','REJECTED');
create table app_users(id uuid primary key default gen_random_uuid(),name text not null,name_normalized text not null unique,role app_role not null default 'FRIEND',password_hash text not null,must_change_password boolean not null default true,required_contribution numeric(12,2) not null default 0 check(required_contribution>=0),bio text,profile_photo_path text,created_at timestamptz not null default now());
create table payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references app_users(id),amount numeric(12,2) not null check(amount>0),status payment_status not null default 'PENDING',screenshot_path text not null,notes text,method text,reference_id text,idempotency_key text not null,approved_at timestamptz,approved_by uuid references app_users(id),rejected_at timestamptz,rejected_by uuid references app_users(id),rejection_reason text,created_at timestamptz not null default now(),unique(user_id,idempotency_key));
create table expenses(id uuid primary key default gen_random_uuid(),amount numeric(12,2) not null check(amount>0),category text not null,description text not null,notes text,created_by uuid not null references app_users(id),deleted_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table albums(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table photos(id uuid primary key default gen_random_uuid(),album_id uuid references albums(id),path text not null,title text not null,created_by uuid references app_users(id),created_at timestamptz not null default now());
create table audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references app_users(id),action text not null,entity_type text not null,entity_id uuid not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create index idx_payments_user on payments(user_id); create index idx_payments_status on payments(status); create index idx_payments_created on payments(created_at desc); create index idx_expenses_category on expenses(category); create index idx_expenses_created on expenses(created_at desc); create index idx_photos_album on photos(album_id); create index idx_audit_created on audit_logs(created_at desc);
alter table app_users enable row level security; alter table payments enable row level security; alter table expenses enable row level security; alter table photos enable row level security; alter table albums enable row level security; alter table audit_logs enable row level security;
create policy "service role only users" on app_users using (auth.role()='service_role'); create policy "service role only payments" on payments using (auth.role()='service_role'); create policy "service role only expenses" on expenses using (auth.role()='service_role'); create policy "service role only photos" on photos using (auth.role()='service_role'); create policy "service role only albums" on albums using (auth.role()='service_role'); create policy "service role only audit" on audit_logs using (auth.role()='service_role');
